UPDATE wms_out_orders
SET wave_id = #{waveId},shipment_strategy = #{shipmentStrategy}
WHERE
	id IN

		#{orderId}

mapper.select:
SELECT
wco.owner_name AS ownerName,
wwm.wave_no AS waveNo,
wh.warehouse_name AS warehouseName,
t.*
FROM wms_out_orders t
LEFT JOIN wms_cargo_owners wco ON wco.id = t.owner_id
LEFT JOIN wms_wave_master wwm ON t.wave_id = wwm.id
LEFT JOIN wms_warehouses wh ON wh.id = t.warehouse_id
WHERE 1 = 1


	AND t.order_no = #{orderNo}




	AND t.status = #{status}




	AND wwm.wave_no = #{waveNo}




	AND t.wave_id = #{waveId}




	AND t.created_waybill = #{createdWaybill}


ORDER BY t.create_time DESC
